//! `svetra compile`: turn a validated document into its output files (docs/compiler.md).

pub mod expr;
pub mod names;
pub mod sql;
pub mod ts;

use crate::diag::Diagnostic;
use sha2::{Digest, Sha256};

/// One generated file. `path` is relative to the folder that holds `svetra.yaml`.
pub struct Output {
    pub path: &'static str,
    pub contents: String,
}

/// The first 12 hex digits of the SHA-256 of the source bytes.
pub fn revision(src: &str) -> String {
    Sha256::digest(src.as_bytes())
        .iter()
        .take(6)
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// Validate `src`, then compile it. Any validation error means no output at all.
/// Warnings and info come back alongside the files.
pub fn compile(
    src: &str,
    file_name: &str,
) -> Result<(Vec<Output>, Vec<Diagnostic>), Vec<Diagnostic>> {
    let diags = crate::report::validate(src);
    if crate::report::has_errors(&diags) {
        return Err(diags);
    }
    let (doc, _) = crate::load::load(src);
    let header = format!(
        "Generated by svetra {} from {file_name} (revision {}). Do not edit.",
        env!("CARGO_PKG_VERSION"),
        revision(src)
    );
    let outputs = vec![
        Output {
            path: "supabase/schemas/svetra.sql",
            contents: format!("-- {header}\n\n{}", sql::schema(&doc)),
        },
        Output {
            path: "src/svetra.gen.ts",
            contents: format!("// {header}\n{}", ts::types(&doc)),
        },
    ];
    Ok((outputs, diags))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn revision_is_a_stable_12_digit_prefix() {
        assert_eq!(revision("abc"), "ba7816bf8f01");
        assert_eq!(revision("abc").len(), 12);
    }

    #[test]
    fn errors_mean_no_output() {
        assert!(compile("svetra: \"0.1\"\nsystem: App\nentities:\n  A:\n    fields:\n      id: { type: uuid }\n", "svetra.yaml").is_err());
    }
}
